<?php
declare(strict_types=1);
namespace App\Application\Taxonomy\Service;
use App\Application\Study\Port\TransactionManagerInterface;use App\Application\Taxonomy\DTO\Request\CreateTaxonomySubjectAliasRequestDto;use App\Application\Taxonomy\DTO\Response\TaxonomySubjectAliasResponseDto;use App\Application\Taxonomy\Mapper\TaxonomySubjectAliasResponseMapper;use App\Domain\Taxonomy\Entity\TaxonomySubjectAlias;use App\Domain\Taxonomy\Repository\TaxonomySubjectAliasRepositoryInterface;use App\Domain\Taxonomy\Repository\TaxonomySubjectRepositoryInterface;use App\Domain\Taxonomy\Service\SubjectTaxonomyService;
final class CreateTaxonomySubjectAliasService { public function __construct(private readonly TaxonomySubjectRepositoryInterface $subjects,private readonly TaxonomySubjectAliasRepositoryInterface $aliases,private readonly SubjectTaxonomyService $taxonomy,private readonly TaxonomySubjectAliasResponseMapper $mapper,private readonly TransactionManagerInterface $transactions){} public function create(CreateTaxonomySubjectAliasRequestDto $input):TaxonomySubjectAliasResponseDto{return $this->transactions->transactional(function()use($input){if($this->subjects->findById($input->subjectId)===null)throw new \DomainException('Assunto nao encontrado.');$alias=trim($input->alias);$normalized=$this->taxonomy->normalize($alias);if($this->aliases->findByNormalizedAlias($normalized)!==null)throw new \DomainException('Este alias ja esta associado a um assunto.');$entity=new TaxonomySubjectAlias($this->uuid(),$input->subjectId,$alias,$normalized);$this->aliases->save($entity);return $this->mapper->toResponse($entity);});} private function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));} }
